// Generated by grafana-k6 on 2026-09-05T07:46:09Z
/**
 * Small deterministic generators for request bodies. Deterministic by (vu, iteration) where it matters so a
 * failure can be replayed; random elsewhere.
 */
import execution from 'k6/execution';

const FIRST = ['Amina', 'Omar', 'Lina', 'Youssef', 'Sara', 'Karim', 'Nour', 'Adam', 'Maya', 'Ali'];
const LAST = ['Hassan', 'Mansour', 'Farid', 'Salem', 'Nasser', 'Khalil', 'Rashid', 'Tahir'];
const CITIES = ['Cairo', 'Riyadh', 'Dubai', 'Berlin', 'Amman'];

export function stamp() {
  return `${execution.vu.idInTest}-${execution.scenario.iterationInTest}`;
}

export function slug(prefix) {
  return `${prefix}-${stamp()}-${Math.random().toString(36).slice(2, 7)}`.toLowerCase();
}

export function email(prefix) {
  return `${slug(prefix)}@load.test`;
}

export function person() {
  const i = execution.vu.idInTest;
  return { firstName: FIRST[i % FIRST.length], lastName: LAST[i % LAST.length] };
}

/** the billing block the checkout form posts; phone 10–15 digits, postal code 4–10 digits */
export function billing(country) {
  const p = person();
  return {
    firstName: p.firstName,
    lastName: p.lastName,
    phone: `0100${String(execution.vu.idInTest).padStart(6, '0')}`,
    country: country || 'EG',
    city: CITIES[execution.vu.idInTest % CITIES.length],
    postalCode: '11511',
    address: `k6 street ${execution.scenario.iterationInTest}`,
    isAgree: true,
  };
}

/** the order body landing-ui posts (libs/types/src/checkout-cart.ts); COD or MANUAL_TRANSFER never redirects */
export function guestOrder(paymentType, emailAddress, country) {
  return {
    paymentType: paymentType || 'COD',
    customer: { emailAddress: emailAddress || email('guest'), billing: billing(country) },
  };
}

export function productDefinition(sku, name, friendlyUrl) {
  return {
    sku,
    visible: true,
    shipeable: true,
    productSpecifications: { weight: 1, height: 10, width: 10, length: 10 },
    descriptions: [{ language: 'en', name, description: `<p>${name}, created by k6.</p>`, friendlyUrl }],
  };
}

export function categoryDefinition(code, name, sortOrder) {
  return { code, visible: true, sortOrder: sortOrder || 10, descriptions: [{ language: 'en', name, friendlyUrl: code }] };
}

export function inventoryEntry(productId, quantity, amount) {
  return { productId, quantity, available: true, price: { amount } };
}

export function contentPageDefinition(slugValue, title) {
  return {
    slug: slugValue,
    showInFooter: true,
    linkToMenu: false,
    noindex: false,
    translations: [{ language: 'en', title, body: `<h2>${title}</h2><p>Written by k6.</p>`, metaDescription: title, keywords: 'k6' }],
  };
}

export function storeDefinition(name, emailAddress) {
  return {
    name,
    email: emailAddress,
    phone: '+10000000000',
    theme: 'BASIS',
    colorTheme: 'LIGHT',
    currency: 'EUR',
    defaultLanguage: 'en',
    supportedLanguages: ['en'],
    address: { country: 'DE', city: 'Berlin', address: '1 Load Street', postalCode: '10115' },
  };
}

export function signupUser(orgName, emailAddress, password) {
  const p = person();
  return { firstName: p.firstName, lastName: p.lastName, emailAddress, organizationName: orgName, password, repeatPassword: password };
}
